const config = { host: "localhost", port: 3000, debug: true };

const configMap = new Map(Object.entries(config));
console.log(configMap.get("port")); // 3000

const config = { host: "localhost", port: 3000, debug: true };

// fromEntries: entries -> obiekt (tu: wszystkie klucze WIELKIMI literami)
const upper = Object.fromEntries(
  Object.entries(config).map(([k, v]) => [k.toUpperCase(), v])
);
console.log(upper); // { HOST: 'localhost', PORT: 3000, DEBUG: true }

// assign: laczenie WIELU obiektow w NOWY obiekt (pusty {} jako cel)
const defaults = { timeout: 5000, retries: 3, debug: false };
const overrides = { debug: true, timeout: 1000 };
const merged = Object.assign({}, defaults, overrides);
console.log(merged); // { timeout: 1000, retries: 3, debug: true }

const defaults = { timeout: 5000, debug: false };
const overrides = { debug: true };

const merged = Object.assign(defaults, overrides); // BLEDNIE: brak pustego {}
console.log(defaults); // { timeout: 5000, debug: true } - ZMUTOWANY!
console.log(merged === defaults); // true - to TEN SAM obiekt

const defaults = { timeout: 5000, debug: false };
const overrides = { debug: true };

const merged = Object.assign({}, defaults, overrides); // POPRAWNIE
console.log(defaults); // { timeout: 5000, debug: false } - NIENARUSZONY
console.log(merged === defaults); // false - to DWA rozne obiekty

